static const char STDLIB_SRC_strutil[] =
"# strutil: handy string helpers that the language doesn't ship in\n"
"# its built-in C string class. Pure MyMo; no dependencies.\n"
"\n"
"# Length of a string. Mirror of MyMo's `s.__len__()` but as a free\n"
"# function so users can write `slen(s)` instead.\n"
"slen = s => s.__len__()\n"
"\n"
"# Return True iff `s` starts with `prefix`.\n"
"fn starts_with(s, prefix):\n"
"    n = prefix.__len__()\n"
"    if s.__len__() < n:\n"
"        return False\n"
"    i = 0\n"
"    while i < n:\n"
"        if s[i] != prefix[i]:\n"
"            return False\n"
"        i = i + 1\n"
"    return True\n"
"\n"
"# Return True iff `s` ends with `suffix`.\n"
"fn ends_with(s, suffix):\n"
"    n = suffix.__len__()\n"
"    m = s.__len__()\n"
"    if m < n:\n"
"        return False\n"
"    i = 0\n"
"    while i < n:\n"
"        if s[m - n + i] != suffix[i]:\n"
"            return False\n"
"        i = i + 1\n"
"    return True\n"
"\n"
"# Split a string on a single-character separator. Returns a list of\n"
"# substrings. Empty separator returns the input unsplit as a 1-list.\n"
"fn split(s, sep):\n"
"    out = []\n"
"    cur = \"\"\n"
"    i = 0\n"
"    n = s.__len__()\n"
"    while i < n:\n"
"        if s[i] == sep:\n"
"            out.append(cur)\n"
"            cur = \"\"\n"
"        else:\n"
"            cur = cur + s[i]\n"
"        i = i + 1\n"
"    out.append(cur)\n"
"    return out\n"
"\n"
"# Join a list of strings with a single-character separator.\n"
"fn join(parts, sep):\n"
"    out = \"\"\n"
"    n = parts.__len__()\n"
"    i = 0\n"
"    while i < n:\n"
"        if i > 0:\n"
"            out = out + sep\n"
"        out = out + parts[i]\n"
"        i = i + 1\n"
"    return out\n"
;

